  form_id: number;
  form_code: string;
  category: "General" | "Procedure" | "Anaesthesia" | "Transfusion" | "HighRiskTreatment" | "AgainstMedicalAdvice" | "Other";
  taken_by: "AnyStaff" | "Doctor" | "Anaesthetist";
  requires_witness: boolean;
