  understanding_confirmed: boolean;
  mode: "Signed" | "EmergencyNote" | "VerbalRefusal" | null;
  patient_capable: boolean | null;
  incapacity_reason: "Minor" | "Unconscious" | "Confused" | "MentalIllness" | "Sedated" | "Other" | null;
  signer: "Patient" | "DecisionMaker" | null;
  signer_name: string | null;
  signer_relationship: "Guardian" | "Attorney" | "Spouse" | "Child" | "Parent" | "Sibling" | "OtherRelative" | "CareProvider" | null;
