/** The stored document (download it with GET /patient-documents/{document_id}/download). */
export interface PatientDocumentUploadOut {
  document_id: number;
  patient_id: number;
  doc_type: "Photo" | "CNIC" | "PanelCard" | "Consent" | "ReferralLetter" | "DeathCertificate" | "AutopsyReport" | "PostMortemReport" | "MedicoLegalReport" | "LabReport" | "Imaging" | "DischargeSummary" | "Prescription" | "Other";
  title: string | null;
  content_type: "application/pdf" | "image/jpeg" | "image/png";
  size_bytes: number;
  /** Brought by the patient from another hospital, laboratory or clinic: show it labelled as an outside document, never as a result of this hospital */
  is_outside: boolean;
  /** The hospital, laboratory or clinic that issued an outside document */
  source_facility: string | null;
  /** The date written on the document (the test, the report, the visit) */
  document_date: string | null;
  uploaded_at: string;
}

/** One active staff member as a picker shows them (GET /staff/lookup): the facts on their badge and the registration their stamp prints, nothing else. */
export interface StaffLookupOut {
  /** The id a form's staff field takes (contrast_doctor_id, employee_id, ...) */
  employee_id: number;
  emp_number: string;
  full_name: string;
  designation: string;
  department_name: string | null;
  /** The council they are registered with (PMDC: a doctor or dentist; PNC: a nurse); null: none */
  license_type: "PMDC" | "PNC" | "Other" | null;
  /** As their stamp prints it, e.g. "PMDC 12345-P"; null: no number on file */
  registration: string | null;
  /** Their login, the id a form's user field takes (an action's owner, a signer, the person told); null: no login (decision 62) */
  user_id: number | null;
}

/** Operations whose surgical record needs work — GET /api/v1/ot/clinical-worklist (who may call: holders of ot.clinical.view). */
export function worklistOtClinical(query?: { mine?: boolean; days?: number; admission_id?: number | null }): Promise<SurgicalWorklistItemOut[]> {
  return api<SurgicalWorklistItemOut[]>("GET", withQuery(`/ot/clinical-worklist`, query), undefined);
}

/** The surgical record of an operation — GET /api/v1/ot/bookings/{booking_id}/surgical-record (who may call: holders of ot.clinical.view). */
export function getRecord(booking_id: number): Promise<SurgicalRecordOut> {
  return api<SurgicalRecordOut>("GET", `/ot/bookings/${booking_id}/surgical-record`, undefined);
}

/** Write the surgeon's pre-operative note — PUT /api/v1/ot/bookings/{booking_id}/pre-op-note (who may call: holders of ot.pre_op.record). */
export function preOpNote(booking_id: number, body: PreOpNoteIn): Promise<SurgicalRecordOut> {
  return api<SurgicalRecordOut>("PUT", `/ot/bookings/${booking_id}/pre-op-note`, body);
}

/** Write the operative note and the post-operative plan (draft) — PUT /api/v1/ot/bookings/{booking_id}/operative-note (who may call: holders of ot.operative_note.write). */
export function writeOperativeNote(booking_id: number, body: OperativeNoteIn): Promise<SurgicalRecordOut> {
  return api<SurgicalRecordOut>("PUT", `/ot/bookings/${booking_id}/operative-note`, body);
}

/** Sign the operative note and the post-operative plan — POST /api/v1/ot/bookings/{booking_id}/operative-note/sign (who may call: holders of ot.operative_note.write). */
export function signOperativeNote(booking_id: number, body: OtRecordSignIn): Promise<SurgicalRecordOut> {
  return api<SurgicalRecordOut>("POST", `/ot/bookings/${booking_id}/operative-note/sign`, body);
}

/** The surgical record (A4) — GET /api/v1/ot/bookings/{booking_id}/surgical-record/print-payload (who may call: holders of ot.clinical.view). */
export function printRecord(booking_id: number): Promise<PrintOut_SurgicalPrintFieldsOut_> {
  return api<PrintOut_SurgicalPrintFieldsOut_>("GET", `/ot/bookings/${booking_id}/surgical-record/print-payload`, undefined);
}

/** The surgical record as a PDF — GET /api/v1/ot/bookings/{booking_id}/surgical-record/pdf (who may call: holders of ot.clinical.view). */
export function recordPdf(booking_id: number): Promise<unknown> {
  return api<unknown>("GET", `/ot/bookings/${booking_id}/surgical-record/pdf`, undefined);
}

/** Append a correction to a signed part of the record — POST /api/v1/ot/bookings/{booking_id}/corrections (who may call: holders of ot.pre_op.record or ot.anaesthesia.record or ot.checklist.record or ot.operative_note.write or ot.recovery.record). */
export function correct(booking_id: number, body: SurgicalCorrectionIn): Promise<SurgicalRecordOut> {
  return api<SurgicalRecordOut>("POST", `/ot/bookings/${booking_id}/corrections`, body, { idempotent: true });
}

